int main(){try{auto covered=createFurCoverageMaterialCandidate({100,150,200});const auto&mask=covered->materials[0];if(mask.image.width!=64||mask.image.height!=128||mask.alphaCutoff!=.5f||mask.translucent)throw std::runtime_error("fur coverage metadata");size_t zero=0,full=0;for(size_t i=0;i<mask.image.rgba.size();i+=4){if(mask.image.rgba[i]!=100||mask.image.rgba[i+1]!=150||mask.image.rgba[i+2]!=200)throw std::runtime_error("coverage color");zero+=mask.image.rgba[i+3]==0;full+=mask.image.rgba[i+3]==255;}if(!zero||!full||mask.image.rgba[(64*64+32)*4+3]!=255||mask.image.rgba[(64*64)*4+3]!=0)throw std::runtime_error("fur coverage mask");auto input=createFurSolidMaterialCandidate({100,150,200});if(input->materials[0].image.rgba!=std::vector<uint8_t>{100,150,200,255})throw std::runtime_error("fur color mismatch");std::weak_ptr<const ModelRenderInputsCandidate>weak=input;{RetainedSceneMaterialGpuCacheCandidate<Images>cache([](const auto&){auto images=std::make_unique<Images>();images->entries.push_back({1});return images;});SceneMaterialInputsCandidate scene;scene.appendOwned(input);struct Scene{std::vector<SceneGpuMaterialAddressCandidate>materials;};Scene draw{{{0,0}}};auto sets=cache.descriptors(draw,scene);if(sets!=std::vector<uint32_t>{1})throw std::runtime_error("fur descriptor mismatch");scene={};input.reset();if(weak.expired())throw std::runtime_error("GPU cache lost material owner");auto owned=weak.lock();auto wrong=createFurSolidMaterialCandidate({1,2,3});bool rejected=false;try{cache.get(*owned,wrong);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("wrong owner accepted");}if(!weak.expired())throw std::runtime_error("GPU cache leaked material");std::cout<<"fur_material_ownership_checks=4 coverage_mask_checks=3 color_exact descriptor_retains_owner mismatched_owner_rejected teardown_releases\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
